using System.Linq;using UnityEngine;using UnityEngine.UI;using UnityEditor;using Demo5.FrontEnd;
public static class InspectTutorial {
 public static string Live(){var c=UnityEngine.Object.FindAnyObjectByType<SettlementController>();var g=c.GetComponent<SettlementTutorialGuide>();var r=g.Marker.rectTransform;var mesh=g.Marker.canvasRenderer?g.Marker.canvasRenderer.GetMesh():null;return "Target "+g.Target?.name+" marker active "+r.gameObject.activeInHierarchy+" position "+r.anchoredPosition+" size "+r.sizeDelta+" renderer "+g.Marker.canvasRenderer+" vertices "+mesh?.vertexCount+" title preferred "+g.Title.preferredHeight+" actual "+g.Title.rectTransform.rect.height+" title "+g.Title.text+" choices "+string.Join(" | ",c.TimePanel.Choices.Select(b=>b.GetComponentInChildren<Text>().text));}
 public static string Run(){string result="";foreach(var path in new[]{"Assets/Prefabs/PartySelection/PartySelectionScreen.prefab","Assets/Prefabs/Settlement/SettlementScreen.prefab"}){var root=PrefabUtility.LoadPrefabContents(path);try{result+=path+"\n";var p=root.GetComponent<PartySelectionController>();if(p){foreach(var t in root.GetComponentsInChildren<Text>(true).Where(t=>!t.transform.IsChildOf(p.Cards[0].transform)&&!t.transform.IsChildOf(p.Details.transform)))result+=t.name+" = "+t.text+" pos "+t.rectTransform.anchoredPosition+" size "+t.rectTransform.sizeDelta+"\n";foreach(var c in p.Cards)result+=c.name+" "+((RectTransform)c.transform).anchoredPosition+" "+((RectTransform)c.transform).sizeDelta+"\n";result+="Details "+((RectTransform)p.Details.transform).anchoredPosition+"\n";}else{var c=root.GetComponent<SettlementController>();result+="intro "+c.Introduction.Action.name+" "+((RectTransform)c.Introduction.Action.transform).anchoredPosition+"\n";}}finally{PrefabUtility.UnloadPrefabContents(root);}}return result;}
}
